1	import { redirect } from "next/navigation";
2	import { RegisterForm } from "@/components/AuthForms";
3	import { AuthShell } from "@/components/marketing/AuthShell";
4	import { ReferralCapture } from "@/components/customer/ReferralCapture";
5	import { currentUser } from "@/lib/auth";
6	import { safeNext } from "@/lib/safe-next";
7	import { googleOauthConfigured } from "@/lib/google-oauth";
8	import { discordOauthConfigured } from "@/lib/discord-oauth";
9	
10	/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
11	const GOOGLE_ERRORS: Record<string, string> = {
12	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
13	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
14	  google_cancelled: "Google sign-in was cancelled.",
15	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
16	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
17	  google_error: "Couldn't finish signing in with Google. Please try again.",
18	  account_suspended: "This account is suspended.",
19	};
20	
21	/** Same convention as GOOGLE_ERRORS — see app/login/page.tsx's DISCORD_ERRORS. */
22	const DISCORD_ERRORS: Record<string, string> = {
23	  discord_unavailable: "Discord sign-in isn't set up on this server yet. Use your email and password.",
24	  discord_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
25	  discord_cancelled: "Discord connection cancelled.",
26	  discord_state: "That Discord sign-in link expired or didn't match. Please try again.",
27	  discord_unverified_email: "Your Discord account needs a verified email to sign up this way. Verify it on Discord, or create a Nxeon account normally and connect Discord from Settings afterward.",
28	  discord_email_taken: "An account with this email already exists. Log in normally, then connect Discord from Settings.",
29	  discord_suspended: "This account is suspended.",
30	  discord_error: "Couldn't finish signing in with Discord. Please try again.",
31	};
32	
33	export default async function RegisterPage({
34	  searchParams,
35	}: {
36	  searchParams: Promise<{ next?: string; error?: string }>;
37	}) {
38	  // Where the visitor was heading before hitting the sign-up wall. Carried
39	  // through the Google OAuth flow so first sign-in lands them where they meant to
40	  // go. Validated by `safeNext` — an unchecked `next` is an open redirect and
41	  // therefore a phishing primitive — so it is never trusted, here or in the action.
42	  const { next, error } = await searchParams;
43	  const dest = safeNext(next ?? null);
44	  // Only ever surface a message from our own fixed map — never echo the raw
45	  // query value into the page.
46	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
47	  const discordError = error ? DISCORD_ERRORS[error] : undefined;
48	  const discordEnabled = await discordOauthConfigured();
49	
50	  // Already signed in? Then this page is a waypoint: send them onward instead of
51	  // asking a paying customer to authenticate again.
52	  const user = await currentUser();
53	  if (user) redirect(dest ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
54	
55	  return (
56	    <AuthShell
57	      heading="Create your account"
58	      sub="Deploy your first server in under a minute."
59	      // Two of these three were untrue. "No credit card required to get started"
60	      // implied a free first server — free deploys are admin-only, and a customer
61	      // with a $0 wallet gets "Insufficient balance. Top up your wallet first."
62	      // And "18+ OS images" was a hardcode the live catalogue passed long ago:
63	      // the homepage counts the same catalogue and renders 31+. A number nothing
64	      // computes goes stale by default, so this states the capability instead.
65	      bullets={[
66	        "Free to create — you pay when you deploy",
67	        "One-click OS images, control panels and apps",
68	        "Pay monthly, cancel anytime",
69	      ]}
70	    >
71	      <ReferralCapture />
72	      <RegisterForm
73	        next={dest ?? undefined}
74	        googleEnabled={googleOauthConfigured()}
75	        googleError={googleError}
76	        discordEnabled={discordEnabled}
77	        discordError={discordError}
78	      />
79	    </AuthShell>
80	  );
81	}
