const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 } });
  const page = await context.newPage();

  const consoleMsgs = [];
  page.on('console', (msg) => consoleMsgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => consoleMsgs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:3021/register', { waitUntil: 'networkidle' });

  const stamp = Date.now();
  const email = `auditor+${stamp}@example.com`;
  const password = 'AuditPass123!';
  const name = 'Audit Tester';

  await page.fill('input[name="name"]', name);
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/reg-01-filled.png' });

  await Promise.all([
    page.waitForURL((u) => !u.pathname.includes('/register'), { timeout: 20000 }).catch(() => {}),
    page.click('button:has-text("Create"), button[type="submit"]'),
  ]);

  await page.waitForTimeout(2500);
  console.log('Post-register URL:', page.url());
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/reg-02-post.png', fullPage: true });

  await context.storageState({ path: '/tmp/nxeon-audit-shots/state-fresh.json' });

  console.log('EMAIL:', email);
  console.log('PASSWORD:', password);
  console.log('--- console/page messages so far ---');
  console.log(consoleMsgs.join('\n'));

  await browser.close();
})();

const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 }, storageState: '/tmp/nxeon-audit-shots/state-fresh.json' });
  const page = await context.newPage();

  const msgs = [];
  page.on('console', (msg) => msgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => msgs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:3021/dashboard', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);

  const modalVisible = await page.locator('[aria-labelledby="heard-title"]').isVisible().catch(() => false);
  console.log('Modal visible on first load:', modalVisible);

  if (modalVisible) {
    await page.click('button:has-text("Skip")');
    await page.waitForTimeout(1000);
    const stillVisible = await page.locator('[aria-labelledby="heard-title"]').isVisible().catch(() => false);
    console.log('Modal visible after clicking Skip:', stillVisible);
  }

  await page.screenshot({ path: '/tmp/nxeon-audit-shots/heard-01-after-skip.png' });

  console.log('--- console messages after first load + skip ---');
  console.log(msgs.join('\n') || '(none)');
  msgs.length = 0;

  // Reload to check it does not reappear, and check for hydration mismatch on reload.
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  const modalOnReload = await page.locator('[aria-labelledby="heard-title"]').isVisible().catch(() => false);
  console.log('Modal visible after reload (should be false):', modalOnReload);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/heard-02-after-reload.png' });

  console.log('--- console messages after reload ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

const { chromium } = require('playwright');

(async () => {
