    const submitBtn = page.locator('button:has-text("Submit")');
    const disabled = await submitBtn.getAttribute('disabled').catch(() => null);
    console.log('Submit button disabled attr after picking option:', disabled);
    if (disabled === null) {
      await submitBtn.click();
      await page.waitForTimeout(1000);
    }
    const afterSubmit = await page.locator('[aria-labelledby="heard-title"]').isVisible().catch(() => false);
    console.log('Modal visible after submit:', afterSubmit);
