  console.log('--- console messages ---');
  console.log(msgs.join('\n') || '(none)');
  msgs.length = 0;

  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  const modalOnReload = await page.locator('[aria-labelledby="heard-title"]').isVisible().catch(() => false);
  console.log('Modal visible after reload (should be false):', modalOnReload);
  console.log('--- console messages after reload ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 }, storageState: '/tmp/nxeon-audit-shots/state.json' });
  const page = await context.newPage();
  const msgs = [];
  page.on('console', (msg) => msgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => msgs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:3021/dashboard', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);

  // 1. Click the "Search anything..." bar
  const searchBar = page.locator('[aria-label="Search anything"]');
  console.log('Search bar visible:', await searchBar.isVisible().catch(() => false));
  await searchBar.click();
  await page.waitForTimeout(700);
  const paletteOpenByClick = await page.locator('[aria-label="Command palette"]').isVisible().catch(() => false);
  console.log('Palette opened by clicking search bar:', paletteOpenByClick);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/cmd-01-click-open.png' });

  // close via Escape
  await page.keyboard.press('Escape');
  await page.waitForTimeout(400);
  console.log('Palette closed after Escape:', !(await page.locator('[aria-label="Command palette"]').isVisible().catch(() => false)));

  // 2. Open via Cmd/Ctrl+K
  await page.keyboard.press('Control+k');
  await page.waitForTimeout(700);
  const paletteOpenByHotkey = await page.locator('[aria-label="Command palette"]').isVisible().catch(() => false);
  console.log('Palette opened by Ctrl+K:', paletteOpenByHotkey);

  // 3. Type a query and check results
  const input = page.locator('input[aria-label*="Search servers"]');
  await input.fill('dashboard');
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/cmd-02-query-dashboard.png' });
  const resultCountDashboard = await page.locator('[aria-label="Command palette"] a, [aria-label="Command palette"] [role="option"], [aria-label="Command palette"] button').count();
  console.log('Result-ish elements for "dashboard":', resultCountDashboard);

  await input.fill('billing');
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/cmd-03-query-billing.png' });
  const resultCountBilling = await page.locator('[aria-label="Command palette"] a, [aria-label="Command palette"] [role="option"], [aria-label="Command palette"] button').count();
  console.log('Result-ish elements for "billing":', resultCountBilling);

  // dump text content of the palette for inspection
  const paletteText = await page.locator('[aria-label="Command palette"]').innerText().catch(() => '(not found)');
  console.log('--- palette text for "billing" query ---');
  console.log(paletteText);

  // 4. Try clicking a result (first link) to navigate
  const firstLink = page.locator('[aria-label="Command palette"] a').first();
  const hasLink = await firstLink.count();
  if (hasLink > 0) {
    const href = await firstLink.getAttribute('href');
    console.log('First result href:', href);
    await firstLink.click();
    await page.waitForTimeout(1500);
    console.log('URL after clicking first result:', page.url());
    const paletteClosedAfterNav = !(await page.locator('[aria-label="Command palette"]').isVisible().catch(() => false));
    console.log('Palette closed after navigating to result:', paletteClosedAfterNav);
  } else {
    console.log('No <a> results found in palette for "billing" -- checking for role=option or buttons instead');
  }
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/cmd-04-after-nav.png' });

  // 5. Reopen and test click-outside to close
  await page.keyboard.press('Control+k');
  await page.waitForTimeout(700);
  const reopened = await page.locator('[aria-label="Command palette"]').isVisible().catch(() => false);
  console.log('Palette reopened via Ctrl+K:', reopened);
  if (reopened) {
    await page.mouse.click(20, 20); // click far corner, outside the palette
    await page.waitForTimeout(500);
    const closedByOutsideClick = !(await page.locator('[aria-label="Command palette"]').isVisible().catch(() => false));
    console.log('Palette closed by click-outside:', closedByOutsideClick);
  }
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/cmd-05-after-outside-click.png' });

  console.log('--- console/page messages throughout ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

