    const themeAttr0 = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    console.log(`${p} initial data-theme:`, themeAttr0);

    await page.screenshot({ path: `/tmp/nxeon-audit-shots/theme-${slug}-a-before.png`, fullPage: true });

    const toggle = page.locator('button[role="switch"][aria-label*="theme"]');
    await toggle.click();
    await page.waitForTimeout(600);
    const themeAttr1 = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    console.log(`${p} after 1st toggle data-theme:`, themeAttr1);
    await page.screenshot({ path: `/tmp/nxeon-audit-shots/theme-${slug}-b-toggled1.png`, fullPage: true });

    // reload and confirm persistence + no flash (check attr immediately after domcontentloaded)
    await page.reload({ waitUntil: 'domcontentloaded' });
    const themeAttrImmediate = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    console.log(`${p} data-theme immediately after reload (domcontentloaded):`, themeAttrImmediate);
    await page.waitForTimeout(1000);
    const themeAttrAfterLoad = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    console.log(`${p} data-theme after full load:`, themeAttrAfterLoad);
    await page.screenshot({ path: `/tmp/nxeon-audit-shots/theme-${slug}-c-after-reload.png`, fullPage: true });

    // toggle back to dark
    const toggle2 = page.locator('button[role="switch"][aria-label*="theme"]');
    await toggle2.click();
    await page.waitForTimeout(600);
    const themeAttr2 = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    console.log(`${p} after 2nd toggle (back) data-theme:`, themeAttr2);
    await page.screenshot({ path: `/tmp/nxeon-audit-shots/theme-${slug}-d-toggled-back.png`, fullPage: true });
  }

  console.log('--- console/page messages throughout ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

