/* Deploy-wizard backdrop.
 *
 * ref-02 (dashboard) carries an aurora ribbon; ref-10 (wizard) carries a lit
 * planet limb in the top-right. They are different screens, so the backdrop is
 * chosen per route in Shell. The arc is deliberately small and low-contrast:
 * in the reference only a ~120px band of the limb is visible, with the flare
 * reading as a point of light rather than a lit hemisphere.
 */
export function GlobeBg() {
  return (
    <div aria-hidden className="pointer-events-none fixed inset-x-0 top-0 z-0 h-[420px] overflow-hidden">
      {/* the PNG's own alpha is feathered to zero on every side, so there is no
          rectangular boundary for the blend mode to expose at any viewport */}
      {/* nx-globe-arc, NOT nx-mix-additive: this is a real photographic PNG
          (an actual lit-planet render), not a pure procedural glow — unlike
          the canvases that only add light and have nothing to show without
          "screen", this one has real colour to fall back on. So light mode
          switches its blend mode instead of hiding it outright (see the
          light-theme override for .nx-globe-arc in globals.css). */}
      <img
        src="/nx/globe-arc.png" alt=""
        className="nx-globe-arc absolute top-[36px] right-[-104px] hidden w-[700px] max-w-none opacity-[0.66] mix-blend-screen md:block"
        style={{ filter: "saturate(0.86) hue-rotate(-7deg)" }}
      />
      <div className="absolute inset-0"
           style={{ background: "linear-gradient(180deg, transparent 46%, color-mix(in srgb, var(--color-bg) 66%, transparent) 78%, var(--color-bg) 100%)" }} />
    </div>
  );
}

/* The "PLAY / HOST / CREATE / TOGETHER" lockup rides with the header content,
   not the backdrop, so it stays legible over the fade. */
export function PlayLockup() {
  return (
    <span aria-hidden
          className="nx-play-lockup ml-1 hidden flex-none flex-col justify-end gap-[7px] self-stretch border-l border-rim-soft pb-1 pl-4
                     text-[10px] font-semibold leading-none tracking-[0.34em] xl:flex">
      <span>BUILD</span><span>HOST</span><span>SCALE</span><span>ANYWHERE</span>
    </span>
  );
}

