const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 }, storageState: '/tmp/nxeon-audit-shots/state.json' });
  const page = await context.newPage();
  const msgs = [];
  page.on('console', (msg) => msgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => msgs.push(`[pageerror] ${err.message}`));

  const pages = ['/dashboard', '/dashboard/deploy', '/dashboard/billing', '/dashboard/settings'];

  for (const p of pages) {
    await page.goto(`http://localhost:3021${p}`, { waitUntil: 'networkidle' });
    await page.waitForTimeout(1000);
    const slug = p.replace(/\//g, '_');

    await page.locator('button[role="switch"][aria-label*="theme"]').click();
    await page.waitForTimeout(900);

    // Scroll through the page in viewport-sized increments, screenshotting each,
    // to inspect the WHOLE page without using fullPage (which can produce
    // stale-paint artifacts for fixed-position backgrounds).
    const scrollHeight = await page.evaluate(() => document.documentElement.scrollHeight);
    let y = 0;
    let shot = 0;
    while (y < scrollHeight) {
      await page.evaluate((yy) => window.scrollTo(0, yy), y);
      await page.waitForTimeout(300);
      await page.screenshot({ path: `/tmp/nxeon-audit-shots/scroll-${slug}-${shot}.png` });
      y += 950;
      shot++;
    }
    console.log(`${p}: scrollHeight=${scrollHeight}, shots=${shot}`);
  }

  console.log('--- console/page messages ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

