"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { CONSENT_EVENT, hasCookieConsent, setCookieConsent } from "@/lib/consent";

/**
 * Bottom cookie OPT-OUT notice. Tracking is default-on (see `marketingAllowed()`
 * in `lib/consent.ts`), so this is an informational, non-blocking notice rather
 * than a gate: the visitor may keep cookies on ("Got it" → "all") or opt out
 * ("Opt out" → "necessary"). Either choice — or a prior choice from a past
 * visit — is stored in the `nxeon_cookie_consent` cookie for one year and hides
 * the notice on this visit and every reload.
 *
 * Mounted once in the root layout by the orchestrator. It renders nothing on
 * the server (and nothing until mounted) to avoid a hydration flash, then
 * appears only when no prior consent cookie is present. Because tracking is
 * already allowed by default, it never blocks the page.
 */

export default function CookieConsent() {
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (!hasCookieConsent()) setVisible(true);
  }, []);

  if (!visible) return null;

  function choose(value: "all" | "necessary") {
    try {
      setCookieConsent(value);
    } catch {
      /* cookies blocked — hide anyway so we don't nag */
    }
    setVisible(false);
    // Tell the chat and feedback widgets to drop back to their normal corner
    // immediately, instead of on the next page load.
    try {
      window.dispatchEvent(new Event(CONSENT_EVENT));
    } catch {
      /* non-fatal — the widgets re-check on their next mount */
    }
  }

  return (
    <div
      role="region"
      aria-label="Cookie notice"
      /*
        `pointer-events-none` on the full-width wrapper, `pointer-events-auto` on
        the card. This wrapper spans the entire bottom of the viewport while the
        card it draws is only `max-w-3xl` and centred — so at 1440px it was
        swallowing clicks across empty space in both bottom corners, including the
        chat bubble and the feedback button ("<div role='dialog' aria-label=
        'Cookie consent' … intercepts pointer events" in the rehearsal's
        actionability log). Nothing invisible should take a click.

        z-[70] beats the chat widget's z-[60]: on a 375px first visit the chat
        bubble painted OVER the "Accept all" row. Between a control the visitor
        must answer and one they may never use, the banner wins — and the widgets
        step aside for it via useConsentPending().
      */
      className="pointer-events-none fixed inset-x-0 bottom-0 z-[70] px-4 pb-4 sm:px-6 sm:pb-6"
    >
      <div className="pointer-events-auto mx-auto flex max-w-3xl flex-col gap-4 rounded-2xl border border-white/[0.1] bg-navy-850/95 p-5 shadow-2xl backdrop-blur-md sm:flex-row sm:items-center sm:gap-6">
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold text-white">We use cookies</p>
          <p className="mt-1 text-[13px] leading-relaxed text-slate-400">
            We use cookies for analytics and advertising to understand how the site is used. You
            can opt out any time — it won&apos;t affect using the site.{" "}
            <Link
              href="/legal/privacy"
              className="font-medium text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200"
            >
              Privacy policy
            </Link>
            .
          </p>
        </div>
        <div className="flex shrink-0 gap-2">
          <button
            type="button"
            onClick={() => choose("necessary")}
            className="btn-secondary px-4 py-2 text-sm"
          >
            Opt out
          </button>
          <button
            type="button"
            onClick={() => choose("all")}
            className="btn-primary px-4 py-2 text-sm"
          >
            Got it
          </button>
        </div>
      </div>
    </div>
  );
}

