 *  pre-written visitor message through the normal send path and closes the menu
 *  (kept open if anonymous identity is still missing, so the chips don't vanish
 *  behind a validation error). "← Back" is handled inline in the render. */
function onChip(chip: FunnelChip) {
  if (chip.kind === "branch") {
    setFunnelNode(chip.id);
    return;
