const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 700 }, storageState: '/tmp/nxeon-audit-shots/state.json' });
  const page = await context.newPage();
  const msgs = [];
  page.on('console', (msg) => msgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => msgs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:3021/dashboard', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text("Got it")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click();
  await page.waitForTimeout(300);

  // 1. 700px tall window, dark mode (default) -- check sidebar nav scroll region
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/sidebar-700h-dark.png' });

  const navInfo = await page.evaluate(() => {
    // Find the scrollable rail element
    const candidates = Array.from(document.querySelectorAll('aside *')).filter(
      (el) => el.scrollHeight > el.clientHeight + 2
    );
    return candidates.map((el) => ({
      tag: el.tagName,
      cls: (el.className || '').toString().slice(0, 100),
      scrollHeight: el.scrollHeight,
      clientHeight: el.clientHeight,
      overflowY: getComputedStyle(el).overflowY,
      scrollbarWidth: getComputedStyle(el).scrollbarWidth,
    }));
  });
  console.log('Scrollable candidates inside <aside>:', JSON.stringify(navInfo, null, 2));

  // 2. Switch to light mode, re-check
  await page.locator('button[role="switch"][aria-label*="theme"]').click();
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/sidebar-700h-light.png' });

  // 3. Scroll the sidebar nav to the bottom and screenshot, to look for hairline gaps
  const scrolled = await page.evaluate(() => {
    const candidates = Array.from(document.querySelectorAll('aside *')).filter(
      (el) => el.scrollHeight > el.clientHeight + 2
    );
    if (candidates[0]) {
      candidates[0].scrollTop = candidates[0].scrollHeight;
      return true;
    }
    return false;
  });
  console.log('Scrolled sidebar nav to bottom:', scrolled);
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/nxeon-audit-shots/sidebar-700h-light-scrolled.png' });

  console.log('--- console/page messages ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

