const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 }, storageState: '/tmp/nxeon-audit-shots/state.json' });
  const page = await context.newPage();
  const msgs = [];
  page.on('console', (msg) => msgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => msgs.push(`[pageerror] ${err.message}`));

  const pages = ['/dashboard', '/dashboard/deploy', '/dashboard/billing'];
  const widths = [900, 1280, 1900];

  for (const p of pages) {
    for (const w of widths) {
      await page.setViewportSize({ width: w, height: 1000 });
      await page.goto(`http://localhost:3021${p}`, { waitUntil: 'networkidle' });
      await page.waitForTimeout(900);
      const gotIt = page.locator('button:has-text("Got it")');
      if (await gotIt.isVisible().catch(() => false)) await gotIt.click();
      await page.waitForTimeout(300);

      const overflow = await page.evaluate(() => {
        const docWidth = document.documentElement.scrollWidth;
        const winWidth = window.innerWidth;
        // find elements that extend past the right edge
        const offenders = [];
        document.querySelectorAll('body *').forEach((el) => {
          const r = el.getBoundingClientRect();
          if (r.right > winWidth + 2 && r.width > 0 && r.width < winWidth * 3) {
            offenders.push({ tag: el.tagName, cls: (el.className || '').toString().slice(0, 80), right: Math.round(r.right), width: Math.round(r.width) });
          }
        });
        return { docWidth, winWidth, overflowing: docWidth > winWidth + 2, offenders: offenders.slice(0, 8) };
      });
      const slug = p.replace(/\//g, '_');
      console.log(`${p} @ ${w}px -> docWidth=${overflow.docWidth} winWidth=${overflow.winWidth} overflow=${overflow.overflowing}`);
      if (overflow.overflowing) {
        console.log('  offenders:', JSON.stringify(overflow.offenders));
      }
      await page.screenshot({ path: `/tmp/nxeon-audit-shots/vp-${slug}-${w}.png`, fullPage: false });
    }
  }

  console.log('--- console/page messages ---');
  console.log(msgs.join('\n') || '(none)');

  await browser.close();
})();

