const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1600, height: 1000 }, storageState: '/tmp/nxeon-audit-shots/state.json' });
  const page = await context.newPage();
  await page.goto('http://localhost:3021/dashboard', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.setItem('nx-theme', 'light'));
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  const gotIt = page.locator('button:has-text(\"Got it\")');
  if (await gotIt.isVisible().catch(() => false)) await gotIt.click();
  await page.waitForTimeout(300);
  await page.locator('[aria-label=\"Open chat\"]').click();
  await page.waitForTimeout(800);
  const info = await page.evaluate(() => {
    const bubble = document.querySelector('[aria-label=\"Open chat\"]')?.closest('div')?.parentElement;
    // find message bubble text node
    const msgEl = Array.from(document.querySelectorAll('div')).find(d => d.textContent.includes('Got a question'));
    const chip = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Compare plans'));
    const out = {};
    if (msgEl) { const cs = getComputedStyle(msgEl); out.msg = { color: cs.color, bg: cs.backgroundColor, cls: msgEl.className.slice(0,100) }; }
    if (chip) { const cs = getComputedStyle(chip); out.chip = { color: cs.color, bg: cs.backgroundColor, cls: chip.className.slice(0,150) }; }
    return out;
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
" 2>&1

